(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["br"] = {"ui":{"skip":"Mont d'an endalc'hadoù","back":"← Distro da AI-gile","lang.button":"Yezh: {name}","lang.dialog":"Dibab ur yezh","lang.search":"Klask yezhoù","lang.none":"Yezh ebet ne glot","lang.notYet":"{name} n'eo ket bet treset c'hoazh","theme.aria":"Cheñch tem: sklaer, teñval pe du","theme.toLight":"Cheñch d'an tem sklaer","theme.toDark":"Cheñch d'an tem teñval","theme.toBlack":"Cheñch d'an tem du (du gwirion, flour evit ar skrammoù OLED)","words.underline":"Islinennañ ar gerioù-mañ war ar bajenn","words.underlineHelp":"Lakait al logodenn war ur ger pikennaouet pe stokit anezhañ evit gwelet petra eo e ster.","index.title":"AI-gile: ho skipailh diorren AI, war un daolenn","index.description":"AI-gile zo un daolenn kanban evit skipailhoù AI a god. Labourat a reont p'emaoc'h o kousket; ur bern berr traoù da zivizout, da amprouiñ ha da asantiñ a vo evidoc'h.","hero.logoAlt":"Arlun taolenn AI-gile","hero.h1.html":"Ho skipailh diorren AI, war un&nbsp;daolenn.","hero.alpha":"🐣 Pre-alfa serret","hero.alphaTitle":"Abred ha n'eo ket echu: trugarez da glask anezhañ!","hero.lede":"Savet e vez ganto p'emaoc'h o kousket. Dihunet e vefec'h gant ur bern berr: un nebeut goulennoù, un nebeut traoù da amprouiñ, un diamant mouk pe zaou. Klik, asantet, distro d'ho kafe.","dl.windows":"Arload Windows","dl.browser":"Lañsañ en ho merdeer","dl.messenger":"📱 Messenger evit ho pellgomz","dl.soon":"Dont a ra abred","dl.notify":"🔔 Lavarit din p'en em zigor","dl.notifySmall":"Alfa pe beta","hero.secondary":"Agile, met ar skipailh n'en deus ket ezhomm eus ur c'hafe stand-up morse. (Stand-up a reont koulskoude.)","pitch.h2":"AI-gile e kement a c'her ha ma karot","pitch.lede":"Dibabit ul hirder, diwar ur ger betek 144. Pep hirder zo ur zeskrivadenn, skrivet evit ar vent-se. Riklit ar riklenn pe implijit an alc'hwezioù-saeta.","pitch.rangeLabel":"Hirder e gerioù","pitch.dice":"🎲 ur stumm all","pitch.words.one":"{n} ger","pitch.words.other":"{n} ger","pitch.letters.one":"{n} lizherenn","pitch.letters.other":"{n} lizherenn","pitch.chars.one":"{n} arouez","pitch.chars.other":"{n} arouez","count.line.html.one":"{n} kartenn war an daolenn bremañ","count.line.html.other":"{n} kartenn war an daolenn bremañ","people.humans.html.one":"👥 {n} den","people.humans.html.other":"👥 {n} den","people.agents.html.one":"🤖 {n} ajant","people.agents.html.other":"🤖 {n} ajant","people.working.html.one":"⚡ {n} o labourat bremañ","people.working.html.other":"⚡ {n} o labourat bremañ","pre.title":"AI-gile: un dra bennak a zo o vezañ savet","pre.description":"Un dra bennak a zo o vezañ savet amañ. Un daolenn ma sav skipailhoù AI ar pezh a c'houlennit, en ur zeskiñ deoc'h a-hed an hent. Evit ar mare, ur pre-alfa serret gant mignoned.","pre.h1":"Un dra bennak a zo o vezañ savet amañ. 🤫","pre.line":"Un daolenn ma sav skipailhoù AI ar pezh a c'houlennit, en ur zeskiñ deoc'h a-hed an hent. Evit ar mare, ur pre-alfa serret gant mignoned.","pre.btn":"🔔 Lavarit din p'en em zigor","pre.peek":"A-dreñv ar werenn: an daolenn wir, war-eeun. Pep kartenn a zo ur varrenn liv.","pre.peekFake":"A-dreñv ar werenn: setu penaos e seblant un daolenn o labourat.","features.aria":"Ar pezh a ra","f.pile.h":"Ur bern evidoc'h","f.pile.html":"<b>Evidoc'h</b> a dastum pep tra a c'hortoz ac'hanoc'h, dre an holl raktresoù: goulennoù, traoù da amprouiñ, labourioù n'hall ober nemet un den. Ho renkad a lavar petra zo da heul ha pet pad a ra.","f.sleep.h":"Skipailhoù a labour p'emaoc'h o kousket","f.sleep.p":"Pep raktres en deus ur penn-skipailh hag ur skipailh ajanted AI. Skrivit un evezhiadenn war ur gartenn ha dihuniñ a ra ar skipailh, ober a ra al labour hag e kas en-dro deoc'h gant pazennoù a c'hall heuliañ un den skuizh.","f.tester.h":"Un amprouer AI a wiriekaat da gentañ","f.tester.p":"Kent ma'z afe tra ebet betek ac'hanoc'h, un amprouer a heul ar pazennoù en un eilad eus an arload hag a ziskouez ar pezh en deus gwelet, gant ur skeudenn skramm. Lenit buan ar re a zo aet mat hag asantit ho klik.","f.proof.h":"Pruvoù, n'eo ket promesaoù","f.proof.p":"Pep treuzkas a ziskouez ar pezh zo cheñchet: ar restroù, an diforc'hioù, ar skeudennoù skramm. Dre ret n'eo ket digeriñ pep arload evit gouzout hag-eñ eo echu.","f.chat.h":"Flapañ gant ho pennoù-skipailh","f.chat.p":"Ur varrenn evel Discord: un arlun dre raktres, diamantoù mouk evit ar pezh en deus ezhomm ac'hanoc'h. Kasit ur mennozh d'ur penn-skipailh; e kartennoù hag e blan e troio, gant ur bouton ✅ Go.","f.tidy.h":"Mirout urzh en-unan","f.tidy.p":"Ar c'hartennoù kar a vez kenstrollet en unan, an titloù mesk a vez reizhet, ha gwiriañ an tokenoù a vir ar c'hod skañv. Nebeutoc'h a draoù da cheñch etrezo, nebeutoc'h da soñjal.","f.private.h":"Ho re, war hoc'h urzhiater","f.private.li1":"An daolenn a red war ho jestr deoc'h-c'hwi hag a respont deoc'h hepken.","f.private.li2":"Ar c'hemennadennoù prevez etre tud a zo sifret penn-da-benn.","f.private.li3":"Kont ebet, heulier ebet, koukiz ebet.","f.lang.h":"En ho yezh","f.lang.p":"Ouzhpenn 120 yezh, eus an nederlandeg, ar c'hembraeg hag ar japoneg betek ar pirat, Yoda ha klingon, gant ur cheñchamant buan en-dro d'ar saozneg evit gerioù ar vicher.","f.service.h":"Eus ur soñj d'ur gwir servij","f.service.p":"Savet ho peus gant an IA un dra a implij an dud bremañ? Merkit anezhañ evel ur servij hag an daolenn a sikour ac'hanoc'h d'e lakaat da vont en-dro mat: gwiriadennoù pad-labour, ur bajenn statud foran, darvoudoù gant un dielfennadenn, cheñchamantoù a c'houlenn ur Mont, eilennoù surentez gwiriet bemdez. Ar Sikour a zesk deoc'h pep pazenn a-hed an hent.","msgr.h2":"AI-gile Messenger: ho skipailh en ho poc'hed","msgr.p1":"Komzit gant ho skipailh AI hep digeriñ ar bord. Flapit gant ho pennoù-raktres hag ho mignoned, gwelit pazennoù-test ur gartenn ha respontit dezho, an holl diouzh ho pellgomz.","msgr.p2":"Evit e liammañ, skanit ur c'hod QR war ho pord. Ar wech kentañ? Ur flap demo mignon a ziskouezo deoc'h an traoù.","msgr.when":"Android da gentañ, goude ur stumm web evit ar pellgomzoù hag an iPhone.","msgr.who":"Ho penn-raktres","msgr.b1":"Prest eo reizhadenn ar mod teñval. Fellout a ra deoc'h ar pazennoù-test?","msgr.b2":"Ya, mar plij!","msgr.b3":"1. Digorit Arventennoù. 2. Dibabit Teñval. Mat eo an neuz?","tl.aria":"Amzeriadur eus ar c'hentañ kaozeadenn betek ar gevrenn-hent","tl.h2":"Eus ar c'hentañ flap d'ar pezh zo da heul","tl.lede":"Deizioù hag eurioù gwir, en ho takad eur deoc'h-c'hwi. Goude hiziv eo ar plan, hep deiziad ebet prometet.","tl.today":"Hiziv","tl.planned":"bet raktreset","tl.cards.one":"{n} kartenn","tl.cards.other":"{n} kartenn","join.h2":"Deuit ganeomp","join.lede":"AI-gile a vez savet gant ur paotr barvek iskis, gant AuDHD hag un nebeud emgannoù gant ar yec'hed-bred, hag un niver bras a ajanted habask. Prevez eo evit bremañ, en un alfa serret gant mignoned. C'hoant hoc'h eus d'e amprouiñ p'en em zigoro?","join.btn":"Lavarout ho c'hoant","join.small":"Skrivañ a raimp deoc'h dre bostel, netra all","footer.tag":"AI-gile. Heulier ebet, koukiz ebet, kafe stand-up ebet.","footer.licence":"Aotre embregerezh","footer.status":"Stad","footer.privacy":"Ar pezh a viromp","footer.thanks":"Galvoù a-drugarez da ChilledChat","form.sending":"O kas…","form.failed":"N'eo ket aet en-dro: klaskit en-dro diwezhatoc'h.","form.offline":"N'eus ket tu da dizhout AI-gile: klaskit en-dro diwezhatoc'h.","form.keep":"Ne implijomp an dra-se nemet evit respont deoc'h, ha goude e lamomp anezhañ. Heulier ebet, koukiz ebet.","form.keepLink":"Ar pezh a viromp","interest.title":"AI-gile: lavarit din p'en em zigoro an alfa","interest.description":"Leuskit ho postel evit gouzout p'en em zigoro alfa serret pe beta AI-gile.","interest.h1":"🔔 Lavarit din p'en em zigor","interest.lede":"AI-gile zo e pre-alfa serret. Leuskit ho postel hag e skrivimp deoc'h unwezh, p'en do un plas evidoc'h.","interest.email":"Ho postel","interest.which":"Peseurt amprouadenn?","interest.alpha":"Alfa serret: abred, garv, kalz cheñchamantoù","interest.beta":"Beta: stabiloc'h, diwezhatoc'h","interest.both":"An eil pe egile, an hini a zeu da gentañ","interest.submit":"Lakait ac'hanon war ar roll","interest.thanks":"Trugarez! War ar roll oc'h.","licence.title":"AI-gile: aotre embregerezh","licence.description":"Implijout a rit AI-gile en ho embregerezh? Goulennit un aotre embregerezh digoust.","licence.h1":"📜 Aotre embregerezh","licence.lede":"Implijout a rit AI-gile er labour? Lavarit deomp piv oc'h hag petra a rit. M'ober a ra un tammig mat, digoust eo an aotre.","licence.company":"Embregerezh","licence.website":"Lec'hienn","licence.what":"Ar pezh a rit","licence.how":"Penaos e sikour ar bed","licence.email":"Postel","licence.submit":"Goulenn","licence.thanks":"Trugarez! Respont a raimp dre bostel.","status.title":"Stad AI-gile","status.h1":"Stad AI-gile","status.quiet":"Peoc'h an holl","status.intro":"Ha mont a ra AI-gile en-dro bremañ? Ar bajenn-mañ a wiri al lec'hienn, rannañ an taolennoù, ar galvoù hag ar pellgargañ bep 5 munutenn.","status.up":"Mont a ra en-dro (respontet e {ms} ms)","status.slow":"N'en deus ket respontet d'ar wiriadenn ziwezhañ, o klask en-dro","status.down":"Paouezet: n'en deus ket respontet d'an div wiriadenn ziwezhañ","status.svc.web":"Lec'hienn","status.svc.web.offers":"Al lec'hienn-mañ: petra eo AI-gile, hag ar furmskrid dedenn","status.svc.boards":"Rannañ an taolennoù","status.svc.boards.offers":"Taolennoù foran, kemennadennoù etre mignoned ha pedadennoù","status.svc.calls":"Galvoù","status.svc.calls.offers":"Mouezh, video ha rannañ skramm en AI-gile","status.svc.download":"Pellgargañ","status.svc.download.offers":"Ar stalier Windows hag al liammoù pediñ","status.checking":"O wiriañ…","status.offline":"N'eus ket tu da dizhout ar servij stad bremañ (o klask en-dro)","status.updated":"hizivaet {ago}","status.justNow":"bremañ just","status.min":"{n} min zo","status.hours":"{n} h zo","status.days":"{n} d zo","privacy.title":"AI-gile: ar pezh a viromp","privacy.h1":"Ar pezh a viromp","privacy.lede":"E berr gomzoù: ar pezh a gasit deomp hepken, ha n'eo ket evit pell.","privacy.only":"Ar pezh a gasit deomp hepken: ar pezh a skrivit en ur furmskrid, evel ho postel. Netra all diwar ho penn.","privacy.sealed":"Siellet eo evit na c'hallfe ket hor servijer e lenn: en ho merdeer a-raok ma'z a kuit (war ur merdeer koshoc'h, kerkent ha ma tegouezh). Hon taolenn hon-unan hepken a c'hall e zigeriñ.","privacy.server":"Lamet e vez diwar ar servijer kerkent ha ma tizh hon taolenn. Kement tra a chomfe eno goude 30 devezh a vez lamet memes tra.","privacy.board":"Ne viromp anezhañ war hon taolenn nemet betek ma vo bet respontet deoc'h, ha goude e lamomp anezhañ eno ivez.","privacy.none":"Heulier ebet, koukiz ebet, dielfennañ ebet.","privacy.local":"Ho yezh hag ho tibab sklaer pe teñval a chom en ho merdeer deoc'h-c'hwi. Ne vezont morse kaset deomp.","privacy.ask":"C'hoant hoc'h eus e vefe lamet abretoc'h? Respontit d'hor postel ha lavarit deomp.","live.h2":"Sellit ouzh e vezañ savet, war-eeun","live.caption":"Pep kartenn a zo kuzhet: gwelout a rit stumm al labour, ket ar gerioù.","live.watching.one":"war-eeun: {n} o sellout","live.watching.other":"war-eeun: {n} o sellout","live.last.now":"Ar gartenn ziwezhañ a zo bet dilec'hiet bremañ","live.last.min.one":"Ar gartenn ziwezhañ a zo bet dilec'hiet {n} min zo","live.last.min.other":"Ar gartenn ziwezhañ a zo bet dilec'hiet {n} min zo","live.last.hour.one":"Ar gartenn ziwezhañ a zo bet dilec'hiet {n} eur zo","live.last.hour.other":"Ar gartenn ziwezhañ a zo bet dilec'hiet {n} eur zo","live.last.day.one":"Ar gartenn ziwezhañ a zo bet dilec'hiet {n} deiz zo","live.last.day.other":"Ar gartenn ziwezhañ a zo bet dilec'hiet {n} devezh zo","live.offline":"Ur pennad diskuizh a gemer an daolenn war-eeun. Distroit a-benn nebeut.","live.cols":"Backlog|Da ober|O vont war-raok|Ar skipailh a wiriañ|Evidoc'h da test|Evit ar skipailh|Graet"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotoù.","Dilezet."]},{"n":2,"texts":["Kanban robotoù.","Ajanted urzhiet.","Mennozhioù, savet."]},{"n":3,"texts":["Kanban evit robotoù.","Mennozhioù da perzhioù.","Kanban ajanted digoust."]},{"n":5,"texts":["Taolenn kanban rediet gant ajanted.","C'hwi a skriv. Ajanted a sav.","Digoust, lec'hel, amprouet, un tammig sot."]},{"n":8,"texts":["Taolenn kanban digoust, ajanted AI a labour warni.","Skrivit ur mennozh. Ajanted a sav anezhañ. Asantit.","Agile evit un den hag kalz robotoù a-bouez."]},{"n":13,"texts":["Un daolenn kanban war hoc'h urzhiater e vez kemeret ar c'hartennoù gant ajanted AI.","Skrivit ur mennozh. Ur skipailh ajanted a sav anezhañ. Un amprouer a wiriekaat.","Digoust, kont ebet, heulier ebet: un daolenn, un nebeut robotoù, hag c'hwi a gomz."]},{"n":21,"texts":["AI-gile zo un daolenn kanban evit labourat gant ajanted AI a god. Kemer a reont ar c'hartennoù; c'hwi a amprouf hag a asant anezho.","Pep raktres en deus ur penn-skipailh hag ur skipailh ajanted AI. Skrivit un evezhiadenn war ur gartenn ha krog a ra ar skipailh.","Un daolenn labourioù personel ha digoust a red war hoc'h urzhiater deoc'h-c'hwi. Robotoù eo al labourerien. An hini a lavar ya eo c'hwi."]},{"n":34,"texts":["Lakaat a rit mennozhioù war un daolenn. Ur skipailh ajanted AI a laka anezho da perzhioù o labourat, a amprouf anezho, hag a gas en-dro anezho deoc'h gant pazennoù da amprouiñ. Tra ebet n'eo echu a-raok ma lavarit.","AI-gile zo un daolenn kanban graet er gêr gant Rich, gant kalz skoazell eus an ajanted a gas bremañ. Digoust eo, a red war hoc'h urzhiater, hag a vez rannet gant mignoned, n'eo ket gwerzhet.","Soñjit en un daolenn kanban boas, gant bannoù eus ar Backlog betek Graet, nemet ar c'hartennoù a vez kemeret gant ajanted AI. Displegañ a reont o araokadenn, goulenn m'int stag, ha gortoz atav ho tudenn war-laez."]},{"n":55,"texts":["AI-gile zo un daolenn kanban m'eo ajanted AI ar skipailh. Pep raktres en deus ur penn-skipailh a blan al labour ha skoazelloù a sav anezhañ. Pa vez prest ur perzh, un amprouer AI a amprouf anezhañ hag a ra ur skeudenn skramm, goude-se e teu en ho pern. Asantit anezhañ, pe skrivit un evezhiadenn hag e adober a raint.","Krog eo bet evel un doare evit un den da heuliañ kalz estrenvaoù kodiñ AI war un dro, ha kresket eo e daolenn wirion. Ober a ra war ho jestr, n'en deus ket ezhomm eus kont, ha n'en deus heulier ebet. Digoust eo evit mignoned ha re c'hoant-gouzout. N'eo ket echu c'hoazh, setu gortozit riblennoù garv hag un souezh a-wechoù.","Setu ar stumm onest. Ret eo deoc'h kaout ar mennozhioù c'hoazh, ha gwiriañ an disoc'hoù c'hoazh. Ar pezh a ra AI-gile eo pep tra etre an daou: miret a ra ar c'hartennoù en urzh, dihuniñ a ra an ajant mat pa skrivit un evezhiadenn, diskouez a ra egzakt ar pezh zo cheñchet, ha lakaat a ra an holl en ur bern berr evidoc'h."]},{"n":89,"texts":["AI-gile zo un daolenn kanban digoust a lañsit war hoc'h urzhiater deoc'h-c'hwi. En tu all d'an dud, pep raktres en deus ur skipailh ajanted AI: ur penn-skipailh a laka ho mennozhioù da gartennoù ha da blan, ha skoazelloù a gemer ar c'hartennoù hervez o raktres. Pa vez savet un dra bennak, un amprouer AI a heul ar pazennoù amprouiñ hag a ziskouez deoc'h ar pezh en deus gwelet. Goude-se e c'hortoz en ur bern anvet Evidoc'h. Asantiñ a rit, pe skrivit un evezhiadenn hag ar skipailh a glask en-dro. Tra ebet ne zeu da Graet hep c'hwi.","Un nebeut traoù na c'hortozit ket marteze. Ur gward-noz a vir ar bann Da ober leun p'emaoc'h o kousket, o tibab kartennoù na c'houlennont ket respont diganeoc'h. Ur jedour tokenoù a ziskouez pet en deus implijet an ajanted hiziv hag ar sizhun-mañ, ha No Token Mode a lavar dezho paouez da zispign. Gallout a rit skrivañ da vignoned, ha sifret eo ar c'hemennadennoù prevez penn-da-benn. An daolenn a gomz tro-dro 120 yezh, en o zouez nederlandeg, flamanteg, pirat ha klingon. Netra eus se ne gousto ur gwenneg, ha den n'eo o klask gwerzhañ se deoc'h.","AI-gile zo ur raktres bihan, personel, n'eo ket un embregerezh. C'hoant en doa Rich da ober war-dro meur a raktres kodiñ AI hep digeriñ pep arload evit o gwiriañ, setu en deus savet gant an ajanted un daolenn evit se, hag implijet an daolenn evit sevel ar rest anezhi. E pre-alfa serret emañ, da lavaret eo e vez mat, dre vras, evit ur bochad mignoned. Pajenn priz ebet, lizher-keleier ebet, plan kresk ebet. M'hoc'h eus c'hoant, gallout a rit goulenn e amprouiñ p'en em zigoro un tammig muioc'h."]},{"n":144,"texts":["AI-gile zo un daolenn kanban evit un den ha kalz ajanted AI. Red a ra war hoc'h urzhiater deoc'h-c'hwi ha digoust eo penn-da-benn. Ouzhpennañ a rit raktresoù, ha pep raktres a zeu gant ur penn-skipailh hag ur skipailh bihan. Flapañ a rit gant ar penn-skipailh, un tammig evel war Discord, ha deskrivañ ur mennozh; ar penn-skipailh a laka anezhañ da gartennoù ha da blan, goude-se e c'hortoz ma wasit war Go. Ar skipailh a labour ar c'hartennoù hervez o raktres, dre un urzhiad-linenn simpl graet evit modeloù yezh. Kent ma teuio tra ebet en-dro deoc'h, un amprouer AI a heul ar pazennoù en un eilad eus an arload hag a stag ur skeudenn skramm. Al labour echu a zeu en ho pern gant ar restroù cheñchet hag an diforc'h. Asantiñ a rit, pe skrivit un evezhiadenn hag ar skipailh a zihun hag a glask en-dro. Hepken c'hwi a c'hall dilec'hiañ ur gartenn da Graet. Kont ebet, heulier ebet, koukiz ebet, ha pep tra a chom war hoc'h urzhiater.","Un devezh gant AI-gile, tro-dro. Da noz e lezit un nebeut evezhiadennoù: ar bouton-mañ zo e plas fall, ar roll-se a rankfe bezañ rummet, ha ne vefe ket un doare teñval. Mont a rit da gousket. An ajanted a lenn an evezhiadennoù, a ra ar cheñchamantoù, a amprouf anezho hag a gas en-dro deoc'h. Ma teu Da ober da vezañ goullo, ar gward-noz a leun anezhañ diwar ar backlog gant kartennoù na c'houlennont ket respont diganeoc'h. Da vintin ur bern berr zo: un nebeut goulennoù hag un nebeut traoù da amprouiñ, pep hini gant pazennoù a c'hall heuliañ un den kousket-koazh ha gant ur skeudenn skramm eus an dra o labourat. Klikañ a rit dre-hont, asantiñ ar re vat ha kas en-dro ar re all. Ur jedour tokenoù a ziskouez ar pezh en deus implijet an holl, ha No Token Mode zo evit ar sizhunioù treut. Goude-se e tebrit ho pred-vintin, ha n'hall ket an ajanted sikour ac'hanoc'h c'hoazh.","Da gentañ, petra n'eo ket AI-gile. N'eo ket ur startup, n'eo ket da werzhañ, ha den ne zastum ho roadennoù. Un daolenn digoust eo a red war hoc'h urzhiater, hep kont, hep heulier ha hep koukiz. Ar pezh eo: ur plas kempenn m'hallit gwelet holl raktresoù kodiñ AI war un dro, gant ur skipailh ajanted a ra ar c'hartennoù ha c'hwi a ra an divizoù. Kenstrollañ a ra ar c'hartennoù kar, reizhañ a ra an titloù mesk, ha selaou a ra penaos e chom skañv ar c'hod. Komz a ra tro-dro 120 yezh, eus an nederlandeg hag ar flamanteg betek ar pirat hag ar c'hlingon. Ar mignoned a c'hall skrivañ an eil d'egile, e prevez ha sifret. Savet eo bet gant Rich hag un niver bras a ajanted a-bouez, dre implijout e-unan peurliesañ. E pre-alfa serret emañ, setu garv eo a-wechoù. M'hoc'h eus c'hoant, goulennit gant jentilezh ha marteze e vo digor deoc'h abred."]}],"quips":{"1":"Ur ger. Dispont. Re zispont marteze.","3":"Tri ger. Muioc'h onest dija eget an darn vrasañ eus ar pajennoù produioù.","8":"Eizh ger. Berroc'h c'hoazh eget ur stand-up.","21":"Ar hirderioù zo story points, dre-vras. Evel just e int.","55":"Pemp ha hanter-kant ger. Div gartenn zo bet echu e-keit ha ma lennit.","144":"Honnezh eo an hini hir. 233 ebet. An ajanted zo aet da gousket."}},"timeline":{"first-idea.name":"Ar c'hentañ mennozh","first-idea.line":"Ar c'hentañ kaozeadenn a-bezh, a-raok ma vije kod ebet.","first-board.name":"Ar c'hentañ taolenn","first-board.line":"Un daolenn a heul he c'hrouidigezh: kartennoù, bannoù, riklañ-ha-lezel, raktresoù.","team-roles.name":"Skipailh ha rolloù","team-roles.line":"Profiloù ajanted, patromoù skipailh, plasoù ha piv a ra petra.","install.name":"Staliañ ha stummoù","install.line":"Ur zip a c'hall ur mignon staliañ, hizivadur emgefreek, kanolioù ha distro d'ar penn-kentañ.","usage-saver.name":"Espern implij","usage-saver.line":"Muzuliañ ar pezh a gousto ar redadennoù, mirout ar c'hod skañv, espern ho harzh.","friends.name":"Mignoned ha rannañ","friends.line":"Kemennadennoù prevez, un adlavar sifret, pedadennoù, rolloù ha raktresoù rannet.","languages.name":"Yezhoù","languages.line":"Pep skrid skramm en ur restr yezh, an nederlandeg hag ar flamanteg da gentañ.","ai-tester.name":"Amprouer AI","ai-tester.line":"Un amprouer a wiriekaat pep treuzkas da gentañ hag a ziskouez ar pezh en deus gwelet.","website.name":"al lec'hienn","website.line":"aigile.lol, ar rakskeudenn hag an amzeriadur-mañ.","streaming.name":"Flap ha streamiñ","streaming.line":"Discord, Twitch, OBS, mod streamer, GIFoù hag emojioù.","no-ai.name":"Stumm hep AI","no-ai.line":"Un daolenn evit tud a god hep AI, ha taolennoù foran.","night-watch.name":"Gward-noz","night-watch.line":"Ur gward ha Scrum Master a vir ar skipailhoù war al labour p'emaoc'h o kousket.","p-more.name":"Kement tra all","p-more.line":"Mennozhioù bihanoc'h a c'hortoz c'hoazh o zro.","p-android.name":"Pellgomzer ha Android","p-android.line":"Tizhout ho taolenn diwar ur pellgomzer, goude-se un arload Android a-orin.","p-release.name":"Alfa ha pelloc'h","p-release.line":"Alfa serret, al lec'hienn vev, goude-se beta.","p-languages.name":"Muioc'h a yezhoù","p-languages.line":"Ouzhpenn kant yezh, ha mod beuzañ evit an dud a zesk.","p-engines.name":"Muioc'h a vekanikoù AI","p-engines.line":"Dibab Claude, Codex pe Gemini evit pep ajant.","p-pro.name":"Boaz a vicherour","p-pro.line":"Skritelloù riskl, dorioù kenaozañ, kartennoù darvoud ha bannoù-diwall.","p-self.name":"Kempenn ac'hanoc'h","p-self.line":"Mod skuizh, kemennoù evit ober war-dro ac'hanoc'h ha 4:20.","p-servers.name":"Servijerioù ha brasaat","p-servers.line":"Arventennoù servijer hollek, rolloù ha plan evit kreskiñ.","p-livestream.name":"Ouzhpennoù streamiñ","p-livestream.line":"Flap Twitch, emojioù personel ha gwel foran bev."},"words":{"button":"📖 Gerioù ar vicher","h":"📖 Gerioù displeget","intro":"Ar gerioù a gavit en AI-gile, e yezh sklaer: e sevel, e cheñch hep risk, e virout en e sav evit an dud a implij anezhañ, ha labourat e skipailh gant an IA.","search":"Klask ur ger…","none":"Ger ebet ne glot.","close":"Serriñ","count":{"one":"{count} ger","other":"{count} ger"},"groups":[{"id":"build","name":"🛠️ E sevel"},{"id":"change","name":"🔀 E cheñch hep risk"},{"id":"run","name":"🛎️ Lakaat ur servij da vont en-dro"},{"id":"team","name":"🤝 Labourat e skipailh (ha gant an IA)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Teuliad kod ar raktres hag e istor klok a gommits, miret ivez war GitHub peurliesañ.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Ul linenn labour distag er c'hod, evit ober kemmoù hep stokañ ouzh ar stumm pennañ.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Ur skeudenn enrollet eus ar c'hod, gant ur notenn verr diwar-benn ar pezh a zo cheñchet. Gallout a rit mont en-dro da unan bepred.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Kas ar skeudennoù enrollet (commit) eus ar c'hevreder-mañ da GitHub, evit ma vint miret ha rannet."},{"id":"merge","g":"build","word":"Merge","text":"Lakaat kemmoù ur branch en-dro er stumm pennañ."},{"id":"pr","g":"build","word":"Pull request","text":"Goulenn e vefe gwiriet kemmoù ur branch ha lakaet er stumm pennañ.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Kempenn ar c'hod hep cheñch ar pezh a ra: restroù bihanoc'h, anvioù sklaeroc'h, nebeutoc'h a adlavar."},{"id":"bug","g":"build","word":"Bug","text":"Un dra ne labour ket evel ma tle.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"Esaeañ ur pezh labour echu evit gwelet hag-eñ ec'h a evel goulennet, a-raok e asantiñ.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Berradur quality assurance (gwarant perzhded): ar gwiriadennoù emgefreek a ya en-dro a-raok ma ya netra war-eeun. Pa vez ruz QA, un dra bennak a zo c'hwitet, ha ne c'hall ket mont war-eeun a-raok ma vo reizhet.","also":["gwiriadennoù perzhded","quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Lakaat ur stumm nevez da vezañ bev, da skouer war ur servijer ma vez implijet gant an dud."},{"id":"release","g":"change","word":"Embannadenn","text":"Ur pakad labour echu gant un anv, a ya war-eeun asambles, gant notennoù berr war ar pezh a zo bet cheñchet. 🚀 Embannadennoù a skriv an notennoù diwar ar c'hartennoù echu.","also":["embannadennoù","release"]},{"id":"rollback","g":"change","word":"Distreiñ","text":"Distreiñ d'ar stumm diwezhañ a yae mat pa vez trubuilhoù gant unan nevez. En AI-gile e ra ur roll-gwiriañ gant ar pazennoù dizober skrivet war pep cheñchamant.","also":["distro","rollback","roll back"]},{"id":"live","g":"change","word":"War-eeun","text":"Ar stumm gwir a implij an dud, ha n'eo ket un eilenn evit amprouiñ traoù. An diorroerien a lavar ivez production (produadur).","also":["produadur","production","live"],"noTip":1},{"id":"change","g":"change","word":"Cheñchamant","text":"Ur cheñchamant steuniet war un dra a fiz an dud ennañ, skrivet da gentañ: petra, perak, ar riskl, pegoulz, ha penaos e zizober. Kregit gant unan gant 🔀 Sevel ur cheñchamant.","also":["cheñchamantoù","goulenn cheñchamant","change request"],"noTip":1},{"id":"risk","g":"change","word":"Riskl","text":"Un dra a c'hallfe mont a-dreuz, gant ur skor hervez pegen gwirheñvel ha pegen fall e vefe. ⚠️ Riskloù a zalc'h anezho en ur roll, ar skor uhelañ da gentañ, pep hini gant un deiziad evit adsellet.","also":["riskloù","marilh ar riskloù","risk"]},{"id":"chgwin","g":"change","word":"Prenestr cheñchamant","text":"Ar mareoù ma c'hall ar cheñchamantoù mont war-eeun, evel un abardaez sioul a Veurzh. E-maez ur prenestr ne c'haller ket echuiñ ur gartenn cheñchamant, nemet e vefe ur pres.","also":["prenestroù cheñchamant","change window"]},{"id":"gonogo","g":"change","word":"Mont / mont ket","text":"Ur votadeg buan just a-raok ma ya ur cheñchamant war-eeun: pep den a rank aprouiñ a lavar Mont pe Mont ket. Ne ya war-raok nemet pa vezont a-du.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Aprouadur","text":"Gortoz un ya a-raok ma krog al labour. Ur gartenn savet gant ur mignon, pe ur cheñchamant, a c'hortoz e ✅ Aprouadurioù betek ma vo aprouet pe nac'het ganeoc'h.","also":["aprouadurioù","approval"]},{"id":"quiettime","g":"change","word":"Mare sioul","text":"Ur prantad, evel ul lanv war-eeun, un diskouez pe an noz, ma ne ya netra war-eeun. Ar skipailhoù a gendalc'h da labourat ha da amprouiñ, met mont war-eeun a c'hortoz betek ma vo echu. E lec'h all e vez graet skorn ar cheñchamantoù anezhañ.","also":["mareoù sioul","skorn ar cheñchamantoù","change freeze"]},{"id":"service","g":"run","word":"Servij","text":"Un dra savet ganeoc'h a fiz an dud ennañ, evel ul lec'hienn pe un arload, ha ma vez taolet evezh outañ evit ma kendalc'ho da vont en-dro. Merkit “Ur servijer eo ar raktres-mañ” ha lavarit petra a ginnig, piv a implij anezhañ ha piv a zo war-garg.","also":["servijoù","service"]},{"id":"uptime","g":"run","word":"Gwiriadenn pad-labour","text":"Ur wiriadenn emgefreek, bep un nebeud munutennoù, e respont c'hoazh ho servij. Ma c'hwit meur a wech diouzh renk, AI-gile a zigor e-unan ur gartenn darvoud.","also":["pad-labour","uptime","uptime check"]},{"id":"statuspage","g":"run","word":"Pajenn statud","text":"Ur bajenn foran a ziskouez hag-eñ ez a ur servij en-dro (gwer, orañjez pe ruz) gant ar c'heloù diwezhañ, evit ma c'hallfe an implijerien sellet e-lec'h goulenn.","also":["pajennoù statud","status page"]},{"id":"incident","g":"run","word":"Darvoud","text":"Un dra torret evit an dud a implij anezhañ bremañ, evel al lec'hienn o vezañ dizarbenn. Ur gartenn 🔥 darvoud a lamm a-us d'al lostennad: lakaat anezhañ da vont en-dro a zeu da gentañ.","also":["darvoudoù","incident"]},{"id":"major","g":"run","word":"Darvoud bras","text":"Un darvoud bras: kalz tud tizhet, pe arc'hant pe roadennoù e riskl. Ur bouton a laka an holl skipailhoù warnañ (strollad), a zihun an hini a zo war-garg hag a c'houlenn un nevesadenn statud bep 30 munutenn.","also":["darvoudoù bras","dramm bras","major incident"]},{"id":"oncall","g":"run","word":"War-garg","text":"Bezañ an hini a respont pa dorr un dra, zoken en noz. Pep servij en deus un ezel eus ar skipailh war-garg, dihunet da gentañ evit e zarvoudoù.","also":["on call","on-call"]},{"id":"replyby","g":"run","word":"Eur respont","text":"Pegeit e c'hall ur gartenn gortoz ur respont kentañ, da skouer un eurvezh evit un darvoud. Goude-se e kav un horolaj ruz, evit na vefe ankouaet netra didrouz. Graet e vez pal respont anezhañ ivez.","also":["eurioù respont","pal respont","response target"]},{"id":"postmortem","g":"run","word":"Dielfennadenn goude an darvoud","text":"Ur sell berr war-dreñv goude un darvoud: petra a zo c'hoarvezet, petra en deus sikouret ha petra cheñch, hep tamall den ebet. Ne c'haller ket serriñ un darvoud hep unan.","also":["post-mortem","postmortem"]},{"id":"problem","g":"run","word":"Kudenn","text":"An abeg kuzh a-dreñv un darvoud pe meur a hini. Ur gartenn 🧩 kudenn a strollad an darvoudoù a zistro atav, evit kavout an abeg ha reizhañ anezhañ da vat.","also":["kudennoù","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Gwir abeg","text":"An abeg gwir ma'z eo torret un dra, ha n'eo ket hepken ar pezh ho peus gwelet o vont a-dreuz. Reizhit ar gwir abeg ha ne zistro ket ken an darvoud.","also":["gwir abegoù","root cause"]},{"id":"workaround","g":"run","word":"Diskoulm a-vremañ","text":"Un doare da virout an traoù en-dro betek ma vo prest ar gwir reizhadenn, evel adloc'hañ un dra pa chom sac'het. Skrivet e vez war ar gartenn kudenn evit na vefe ret da zen e gavout en-dro.","also":["diskoulmoù a-vremañ","workaround"]},{"id":"knownerror","g":"run","word":"Fazi anavezet","text":"Ur gudenn a zo komprenet he abeg hag he deus un diskoulm a-vremañ, met n'eo ket reizhet c'hoazh. 🧩 Fazioù anavezet a ro ar roll anezho, evit ma implijfe an holl an diskoulm e-lec'h kleuzañ en-dro.","also":["fazioù anavezet","known error"]},{"id":"runbook","g":"run","word":"Levr-kuzul","text":"Kemennadurioù pazenn ha pazenn evit reizhañ ur seurt trubuilh anavezet, evit ma vefe graet en hevelep doare, buan, bep tro. Goude un darvoud bras e c'hall ar skipailh kinnig unan deoc'h da aprouiñ.","also":["levrioù-kuzul","runbook"]},{"id":"backup","g":"run","word":"Eilenn surentez","text":"Un eilenn eus ho roadennoù enrollet a-raok, evit en em dennañ ma vez kollet pe gwastet un dra. AI-gile a ra un eilenn surentez eus ho taolennoù bemdez.","also":["eilennoù surentez","backup"]},{"id":"restore","g":"run","word":"Assav","text":"Lakaat roadennoù en-dro diwar un eilenn surentez. N'eo talvoudus da vat un eilenn surentez nemet pa ouzit e c'haller assevel anezhi, setu e talv ar boan he amprouiñ a-wechoù.","also":["assavet","restore"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ideennoù ha labour n'int ket bet steuñvet c'hoazh. Netra ne vez labouret betek ma vo dilec'hiet da Da ober."},{"id":"sprint","g":"team","word":"Sprint","text":"Ur prantad berr a labour (aliesoc'h ur sizhun pe zaou) gant un hevelep kartennoù da echuiñ.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Ur gwiriadenn herrek: ar pezh en deus graet pep esaouad, ar pezh a raio da heul, hag ar pezh a ro harz dezhañ.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Ur bord gant bannadoù (Da ober, O vont war-raok, Graet) ma tremen ar c'hartennoù a-gleiz da zehou p'emañ al labour o vont en-dro."},{"id":"wip","g":"team","word":"Bevenn WIP","text":"Labour e-kerzh: ar muiañ a gartennoù a c'hall dalc'hel ur bannad, evit ma echuo ar skipailh traoù a-raok kregiñ en re all.","also":["WIP"]},{"id":"dod","g":"team","word":"Despizadur Echu","text":"Roll-gwiriañ berr ar skipailh war ar pezh a dalvez “echu”, evel amprouet ha displeget, a-raok ma vo roet ur gartenn deoc'h. E c'hevell, an Despizadur Prest, a lavar pegoulz eo sklaer a-walc'h ur gartenn evit kregiñ.","also":["Despizadur Prest","Definition of Done","Definition of Ready"]},{"id":"testpile","g":"team","word":"Stok amprouennoù","text":"Ar c'hartennoù echu a c'hortoz ma vint amprouet ganeoc'h, an eil goude egile. Asantit unan pe adkasit anezhi gant un notenn, hag an hini war-lerc'h a zeu.","also":["stokoù amprouennoù","test pile"]},{"id":"retro","g":"team","word":"Sell war-geñver","text":"Ur sell war-dreñv war an doare ma labour ar skipailh, evit en em glevout war un dra d'ober gwelloc'h. En AI-gile e kinnig ur sell war-geñver ur cheñchamant e doareoù labourat ar skipailh, ha c'hwi a lavar Go pe Ket c'hoazh.","also":["retro","retrospective"]},{"id":"peerreview","g":"team","word":"Adwelet kenstrollet","text":"Un eil daoulagad: un IA all a wir labour pep kartenn a-raok ma tizh ac'hanoc'h, evit ma tremenfe nebeutoc'h a fazioù.","also":["adwelet ar c'hod","peer review","code review"]},{"id":"swarm","g":"team","word":"Strollad","text":"An holl d'ar stur: pep skipailh a lez e labour all evit sikour war ur raktres mallus betek ma vo diskoulmet. Ar raktresoù all a c'hortoz e-keit-se.","also":["swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"An hini a vir al labour o redek: gwelet a ra ar c'hartennoù sac'het, broudañ a ra ar skipailhoù hag e tegas da soñj deoc'h ar pezh a c'hortoz. En AI-gile e ra al Lead Scrum Master kement-se evit an holl raktresoù.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"Un AI a labour e-unan war ul labour: lenn a ra ar c'hod, ober kemmoù, lakaat gwiriadennoù da red, ha danevellañ.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"Ar poellad ma vez kontet implij an AI: war-dro un nebeud lizherennoù testenn lennet pe skrivet. Nebeutoc'h a dokenoù, muioc'h a chom eus ho steuñvenn.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Ur gemenn vihan a red e-unan en un nebeut-amzer termenet, d.s. pa loc'h un estez AI, evit ma klevo ar skipailh hoc'h evezhiadennoù.","also":["hooks"]}]}};
